function tokenize(text) {
  const m = text.toLowerCase().match(/[а-яёa-z0-9]+/g) || [];
  return m.filter(t => t.length > 2 && !STOPWORDS.has(t));
}
const payload = JSON.parse($input.first().json.payload);
const qTokens = new Set(tokenize(payload.question));
const scored = payload.corpus.map(doc => {
  const dTokens = new Set(tokenize(doc.text));
  let overlap = 0; for (const t of qTokens) if (dTokens.has(t)) overlap++;
  return {id: doc.id, overlap};
});
scored.sort((a,b)=>b.overlap-a.overlap);
const keyword_rank = scored.map(s=>s.id);
return [{json: {...payload, keyword_rank, keyword_scores: scored}}];

const kw = $('Keyword overlap').first().json;
const qvec = $input.first().json.data[0].embedding;
function cos(a,b){let d=0,na=0,nb=0;for(let i=0;i<a.length;i++){d+=a[i]*b[i];na+=a[i]*a[i];nb+=b[i]*b[i];}return d/(Math.sqrt(na)*Math.sqrt(nb));}
const scored = kw.corpus.map(doc => ({id: doc.id, score: cos(qvec, doc.embedding)}));
scored.sort((a,b)=>b.score-a.score);
const vector_rank = scored.map(s=>s.id);
return [{json: {...kw, vector_rank, vector_scores: scored}}];

const d = $input.first().json;
function rrf(rankA, rankB, k=60) {
  const scores = {};
  [rankA, rankB].forEach(rank => { rank.forEach((id, i) => {
    scores[id] = (scores[id]||0) + 1/(k+i+1); }); });
  return Object.keys(scores).sort((a,b)=>scores[b]-scores[a]);
}
const hybrid_rank = rrf(d.keyword_rank, d.vector_rank, 60);
const TOP_N = Math.min(10, hybrid_rank.length);
const topIds = hybrid_rank.slice(0, TOP_N);
const byId = {}; d.corpus.forEach(c=>byId[c.id]=c.text);
const candidatesText = topIds.map((id,i)=>`${i+1}. ${byId[id]}`).join('\n\n');
return [{json: {...d, hybrid_rank, top_ids: topIds, candidates_text: candidatesText}}];

