const d = $('RRF fusion (hybrid)').first().json;
const resp = $input.first().json;
let content = null; try { content = resp.choices[0].message.content; } catch(e) {}
let order = null;
if (content) {
  const m = content.match(/\[[\d,\s]+\]/);
  if (m) { try { const parsed = JSON.parse(m[0]); const n = d.top_ids.length;
    const isPerm = parsed.length===n && new Set(parsed).size===n && parsed.every(x=>x>=1&&x<=n);
    if (isPerm) order = parsed; } catch(e) {} }
}
let rerankedIds = d.top_ids; let parseOk = false;
if (order) { rerankedIds = order.map(i => d.top_ids[i-1]); parseOk = true; }
function rankOf(list, id) { const i = list.indexOf(id); return i===-1 ? null : i+1; }
const rHybrid = rankOf(d.hybrid_rank, d.gold_doc_id);
const rReranked = rankOf(rerankedIds, d.gold_doc_id);
const summary = `Вопрос: ${d.question}\n` +
  `Эталонный документ: ${d.gold_doc_id}\n\n` +
  `keyword: ранг эталона = ${rankOf(d.keyword_rank, d.gold_doc_id) ?? 'не найден'} (из ${d.keyword_rank.length})\n` +
  `vector:  ранг эталона = ${rankOf(d.vector_rank, d.gold_doc_id) ?? 'не найден'} (из ${d.vector_rank.length})\n` +
  `hybrid (RRF): ранг эталона = ${rHybrid ?? 'не найден'} (из ${d.hybrid_rank.length})\n` +
  `hybrid + LLM-реранкер: ранг эталона = ${rReranked ?? ('не входил в top-' + d.top_ids.length)} (parse_ok=${parseOk})\n\n` +
  `top-${d.top_ids.length} до реранка: ${d.top_ids.join(', ')}\n` +
  `top-${d.top_ids.length} после реранка: ${rerankedIds.join(', ')}`;
return [{json: {...d, reranked_ids: rerankedIds, parse_ok: parseOk, summary}}];
